    // ---- 10. Xuange unlock: be neighbours with all other players
    {
        MuCase c;
        c.fixes = lvl;
        c.name = "xuange unlock";
        c.factions = {-1, E, SOL};
        c.actPick = firstEnabled;
        bool before = false;
        c.setup = [&](Game& g) {
            for (const LeaderState& ls : g.players[f].leaders)
                if (kLeaders[ls.leader].type == kCommander) before = ls.status != kLocked;
            for (int q = 0; q < g.numPlayers; ++q)
                if (q != f) g.systems[size_t(g.players[q].homeSystem)].space[f].add(UnitType::Destroyer, 1);
            return true;
        };
        MuResult r = muRun(c);
        int st = -1;
        for (const LeaderState& ls : r.atAct.players[f].leaders)
            if (kLeaders[ls.leader].type == kCommander) st = ls.status;
        report("10 Xuange unlock (neighbours with everyone)", r.acted && !before && st != kLocked,
               std::string(before ? "ALREADY unlocked at the start" : "locked at the start") + (st != kLocked ? ", unlocked" : ", still LOCKED"));
    }
    // ---- 11 / 12. Conservator Procyon (hero): a frontier token in each system without planets and without one; then explore each
    // frontier token in a system with your ships; then purge. 12 (Thunder's Edge): a system with only a space station has no
    // planets - a frontier token at setup (TE rulebook) and from the hero
    for (int st = 0; st < 2; ++st) {
        int W = -1, S = -1;
        std::vector<int> cleared;
        bool atSetup = false;
        MuCase c;
        c.fixes = lvl;
        c.modules = st ? kModThundersEdge : 0;
        c.name = st ? "procyon station" : "procyon";
        c.factions = {-1, E, SOL};
        c.act = 6000 + int(Ab::EmpyreanHero);
        c.setup = [&](Game& g) {
            muLeader(g, f, kHero, kReady);
            cleared.clear();
            W = S = -1;
            for (size_t x = 0; x < g.systems.size(); ++x) {
                SystemState& s = g.systems[x];
                if (s.offBoard || s.isHyperlane() || s.home >= 0) continue;
                bool onlyStations = !s.planets.empty();
                for (int16_t p : s.planets) onlyStations = onlyStations && isStation(g, p);
                if (onlyStations && S < 0) {
                    S = int(x);
                    atSetup = s.frontier;
                    s.frontier = false;
                }
                if (!s.planets.empty() || !s.frontier) continue;
                bool none = true;
                for (int q = 0; q < kSides; ++q) none = none && s.space[size_t(q)].empty();
                if (!none) continue;
                if (W < 0) {
                    W = int(x);
                    s.space[f].add(UnitType::Destroyer, 1);
                } else if (cleared.size() < 2) {
                    cleared.push_back(int(x));
                    s.frontier = false;
                }
            }
            return W >= 0 && cleared.size() == 2 && (!st || S >= 0);
        };
        MuResult r = muRun(c);
        bool placed = !cleared.empty();
        for (int x : cleared) placed = placed && r.end.systems[size_t(x)].frontier;
        const bool explored = W >= 0 && !r.end.systems[size_t(W)].frontier && lineWith(r, "explores the frontier token in");
        int hs = -1;
        for (const LeaderState& ls : r.end.players[f].leaders)
            if (kLeaders[ls.leader].type == kHero) hs = ls.status;
        if (!st) {
            report("11 Conservator Procyon", r.acted && placed && explored && hs == kPurged,
                   std::string(placed ? "tokens placed where missing" : "tokens NOT placed") + (explored ? ", the one with our ships explored" : ", NOT explored") +
                       (hs == kPurged ? ", purged" : ", NOT purged"));
        } else {
            const bool heroPut = S >= 0 && r.end.systems[size_t(S)].frontier;
            report("12 a space station only (Thunder's Edge)", r.setUp && r.acted && atSetup && heroPut,
                   !r.setUp ? std::string("no station-only system on the boards tried")
                            : std::string("frontier token at setup: ") + (atSetup ? "yes" : "NO") + ", from the hero: " + (heroPut ? "yes" : "NO"));
        }
    }
    // ---- 13. Dynamo (flagship): after ANY player's unit in its system or an adjacent one uses Sustain Damage, the Empyrean may
    // spend 2 influence to repair it
    {
        bool own = false, other = false, sustOther = false, sustOwn = false;
        MuResult r;
        for (uint32_t k = 0; k < 10 && !(sustOther && sustOwn); ++k) {
            int Hs = -1, T = -1;
            own = other = false;
            MuCase c;
            c.fixes = lvl;
            c.name = "dynamo";
            c.seed = 9090 + k * 37;
            c.factions = {-1, E, SOL};
            c.actor = o;
            c.act = 0;
            c.setup = [&](Game& g) {
                Hs = g.players[o].homeSystem;
                T = nextTo(g, Hs);
                if (T < 0) return false;
                int Y = -1;  // (the flagship next to the combat, out of it)
                for (int16_t a : g.systems[size_t(T)].adj)
                    if (Y < 0 && a != Hs && !g.systems[size_t(a)].offBoard && !g.systems[size_t(a)].isHyperlane() && g.systems[size_t(a)].home < 0 &&
                        !isAnomaly(g, a) && a != g.mecatol())
                        Y = a;
                if (Y < 0) return false;
                for (int q = 0; q < kSides; ++q) clearShips(g, q, Y);
                g.systems[size_t(Y)].space[f].add(UnitType::Flagship, 1);
                g.systems[size_t(T)].space[f].add(UnitType::Dreadnought, 2);
                clearShips(g, o, Hs);
                g.systems[size_t(Hs)].space[o].add(UnitType::Dreadnought, 3);
                freeTokens(g, o, 5);
                g.players[f].tradeGoods = 6;
                return true;
            };
            c.drive = moveDrive(o, [&] { return T; }, [&] { return std::vector<int>{Hs, -1, DN, 3}; },
                                [&](const Game&, const Decision& d, Answer& a) {
                                    if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::Dynamo)) {
                                        (d.prompt.find("Sol's") != std::string::npos ? other : own) = true;
                                        return pickOne(a, 1);
                                    }
                                    return false;
                                });
            r = muRun(c);
            sustOther = lineWith(r, "Sol's Dreadnought sustains damage");
            sustOwn = lineWith(r, "Empyrean's Flagship sustains damage") || lineWith(r, "Empyrean's Dreadnought sustains damage");
        }
        report("13 Dynamo (any player's unit)", sustOther && other && (!sustOwn || own) && lineWith(r, "(Dynamo)"),
               std::string(sustOwn ? (own ? "own unit: asked" : "own unit: NOT asked") : "no own unit sustained") + ", " +
                   (sustOther ? (other ? "Sol's unit: asked" : "Sol's unit: NOT asked") : "no Sol unit sustained in 10 tries"));
    }
    // ---- 14. Watcher (mech): remove it from a system with or next to another player's units to cancel an action card they play
