        c.drive = moveDrive(f, [&] { return S; }, [&] { return std::vector<int>{H, -1, CV, 1, H, -1, INF, 1}; }, [&](const Game&, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::ScavengerZeta)) {
                zeta = true;
                return pickOne(a, k ? 1 : 0);
            }
            return false;
        });
        MuResult r = muRun(c);
        const bool scav = lineWith(r, "(Scavenge)");
        int mechs = 0;
        if (S >= 0)
            for (int16_t x : r.end.systems[size_t(S)].planets) mechs += r.end.planets[size_t(x)].units[f].count(UnitType::Mech);
        if (!k) report("2 Scavenge", r.acted && scav, scav ? "1 trade good for the planet taken" : "NO trade good");
        else report("3 Scavenger Zeta", r.acted && zeta && mechs == 1, std::string(zeta ? "offered" : "NOT offered") + ", " + std::to_string(mechs) + " mech placed");
