    // ---- 8 / 9. Skarvald & Torvar (agent): "When the active player produces 1 or more hits during a round of combat: You may exhaust this
    // card to allow that player to produce 1 additional hit" - the Ghemina's own attack (8); Sol's attack on the Letnev, the Ghemina a
    // person, nothing promised (9)
    for (int k = 0; k < 2; ++k) {
        int T = -1;
        bool asked = false;
        const int who = k ? o : f, foe = k ? l : o;
        std::vector<int> mv;
        MuCase c = kase(k ? "skarvald person" : "skarvald");
        c.actor = who;
        c.setup = [&](Game& g) {
            const int H = g.players[who].homeSystem;
            T = firstAdj(g, H, 0);
            if (T < 0) T = firstAdj(g, H, -1);
            if (T < 0) return false;
            clearShips(g, who, H);
            g.systems[size_t(H)].space[who].add(UnitType::Dreadnought, 3);
            mv = {H, -1, DN, 3};
            g.systems[size_t(T)].space[foe].add(UnitType::Destroyer, 3);
            if (k) g.players[f].human = true;
            freeTokens(g, who, 6);
            return true;
        };
        c.drive = actDrive(who, &T, &mv, nullptr, [&](const Game&, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::DsSkarvald)) {
                asked = true;
                return pickOne(a, 1);
            }
            return false;
        });
        MuResult r = muRun(c);
        const bool more = lineWith(r, "raid heralds sound");
        report(k ? "9 Skarvald & Torvar for Sol (a person's agent)" : "8 Skarvald & Torvar", r.acted && asked && more,
               std::string(asked ? "offered" : "NOT offered") + (more ? ", 1 more hit" : ""));
    }
    // ---- 10 / 11. Jarl Vel & Jarl Jotrun: "After you win a combat in a system that contains no planets ..." - a space combat won in an
    // empty system (10); War Song Implants: "After you win a space combat, you may ready 1 planet you control" (11)
    {
        int T = -1, X = -1;
        bool asked = false;
        std::vector<int> mv;
        MuCase c = kase("jarls space");
        c.actor = f;
        c.setup = [&](Game& g) {
            const int H = g.players[f].homeSystem;
            T = firstAdj(g, H, 0);
            if (T < 0) return false;
            clearShips(g, f, H);
            g.systems[size_t(H)].space[f].add(UnitType::Dreadnought, 3);
            mv = {H, -1, DN, 3};
            g.systems[size_t(T)].space[o].add(UnitType::Destroyer, 1);
            setLeader(g, f, kCommander, kReady);
            giveTech(g, f, "dsghemg");
            X = g.systems[size_t(H)].planets[0];
            freeTokens(g, f, 6);
            return true;
        };
        c.atActSet = [&](Game& g) { g.planets[size_t(X)].exhausted = true; };
        c.drive = actDrive(f, &T, &mv, nullptr, [&](const Game&, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::DsWarSong)) {
                asked = true;
                return pickOne(a, has(d, X) ? X : d.options[0].id);
            }
            return false;
        });
        MuResult r = muRun(c);
        report("10 Jarl Vel & Jarl Jotrun (a space combat where there are no planets)", r.acted && lineWith(r, "takes 1 trade good from the raid"),
               lineWith(r, "takes 1 trade good from the raid") ? "1 trade good" : "NO trade good");
        report("11 War Song Implants", r.acted && asked && X >= 0 && !r.end.planets[size_t(X)].exhausted,
               std::string(asked ? "offered" : "NOT offered") + (X >= 0 && !r.end.planets[size_t(X)].exhausted ? ", the planet readied" : ", the planet still exhausted"));
    }
    // ---- 12. Jarl Vel & Jarl Jotrun's unlock: "Have 2 flagships on the game board"
