    // ---- 2 / 3. Mobile Command: "The system that contains your flagship is your home system" - the All Mother moves next door: that
    // system is their home, Ghoti Space no longer is ("The Ghoti Space system is not a home system") (2); the planet card: "When you
    // move 1 or more ships into a system that contains no planets, gain 1 commodity" (3)
    {
        int H = -1, T = -1;
        std::vector<int> mv;
        MuCase c = kase("mobile command");
        c.actor = f;
        c.setup = [&](Game& g) {
            H = g.players[f].homeSystem;
            T = firstAdj(g, H, 0);
            if (T < 0) return false;
            mv = {H, -1, FS, 1, H, -1, FF, 2, H, -1, INF, 3};
            g.players[f].commodities = 0;
            freeTokens(g, f, 6);
            return true;
        };
        c.drive = actDrive(f, &T, &mv, nullptr, nullptr);
        MuResult r = muRun(c);
        const bool moved = T >= 0 && r.end.players[f].homeSystem == T && r.end.systems[size_t(T)].home == f && r.end.systems[size_t(H)].home < 0;
        report("2 Mobile Command (the home moves with the flagship)", r.acted && moved, moved ? "the new system is their home, Ghoti Space is not" : "the home did NOT move");
        report("3 the Ghoti planet card (ships into a system without planets)", r.acted && r.end.players[f].commodities == 1 && lineWith(r, "in the void"),
               std::to_string(r.end.players[f].commodities) + " commodity (1)");
    }
    // ---- 4 / 5. Mobile Command: "you cannot score public objectives if your flagship is not on the game board" - Erect a Monument met
    // (12 trade goods): scored with the All Mother on the board (4), not without her (5)
    for (int k = 0; k < 2; ++k) {
        const int mon = findObjective("monument");
        MuCase c = kase(k ? "no flagship no publics" : "flagship publics");
        c.actor = f;
        c.actPick = stratPick;
        c.untilRound = 1;
        c.setup = [&](Game& g) {
            for (auto* v : {&g.stage1Deck, &g.stage1Rest}) v->erase(std::remove(v->begin(), v->end(), int16_t(mon)), v->end());
            g.publicObjectives = {int16_t(mon)};
            g.players[f].tradeGoods = 12;
            if (k) {
                const int H = g.players[f].homeSystem;
                clearShips(g, f, H);
                g.systems[size_t(H)].space[f].add(UnitType::Cruiser, 1);
            }
            return true;
        };
        c.drive = [&](const Game&, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::ScorePublic && has(d, mon)) return pickOne(a, mon);
            return false;
        };
        MuResult r = muRun(c);
        const bool sc = hasScored(r.end, f, mon);
        if (k == 0) report("4 Mobile Command (a public objective with the flagship on the board)", r.finished && sc, sc ? "Erect a Monument scored" : "NOT scored");
        else report("5 Mobile Command (no public objective without the flagship)", r.finished && !sc, sc ? "Erect a Monument scored (WRONG)" : "not scored");
    }
    // ---- 6 / 7. All Mother: "this unit is also treated as a space dock with a PRODUCTION value equal to the number of tokens in your
