    // ---- 12. Parallel Production: "When you produce 1 or more units, you may produce 1 additional unit in each of 2 systems that contain
    // 1 or more of your ships and 1 of your command tokens"
    {
        int H = -1, S1 = -1, S2 = -1;
        MuCase c = kase("parallel production");
        c.actor = f;
        c.setup = [&](Game& g) {
            H = g.players[f].homeSystem;
            for (int16_t t : g.systems[size_t(H)].adj)
                if (plainSys(g, t, -1)) (S1 < 0 ? S1 : S2) = t;
            if (S1 < 0 || S2 < 0) return false;
            Force& sp = g.systems[size_t(H)].space[f];
            sp.n[int(UnitType::Fighter)] = sp.n[int(UnitType::Infantry)] = 0;
            g.players[f].tradeGoods = 10;
            setLeader(g, f, kAgent, kExhausted);
            giveTech(g, f, "dsghoty");
            freeTokens(g, f, 6);
            for (int s : {S1, S2}) {
                g.systems[size_t(s)].space[f].add(UnitType::Destroyer, 1);
                g.systems[size_t(s)].tokens = uint16_t(g.systems[size_t(s)].tokens | (1u << f));
            }
            return true;
        };
        auto parallel = std::make_shared<int>(0);
        c.drive = homeProduce(&H, {{INF, 1}}, [&, parallel](const Game&, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::DsParallel)) return pickOne(a, has(d, S1) ? S1 : has(d, S2) ? S2 : -1);
            if (d.player == f && d.kind == DecisionKind::Produce && (d.system == S1 || d.system == S2)) {
                ++*parallel;
                return planFor(a, {{DD, 1}});
            }
            return false;
        });
        MuResult r = muRun(c);
        const int a1 = S1 >= 0 ? sumOf(r.end, S1, f, UnitType::Destroyer) : -1, a2 = S2 >= 0 ? sumOf(r.end, S2, f, UnitType::Destroyer) : -1;
        report("12 Parallel Production", r.acted && a1 == 2 && a2 == 2, std::to_string(a1) + " and " + std::to_string(a2) + " destroyers in the two systems (2 and 2)");
    }
    // ---- 13. Ghoti Relay (Sol holds it): "At the start of your turn: Place this card in your play area to produce up to 2 ships in a
    // system that contains 1 or more of your ships. At the start of the status phase, return this card to the Ghoti Player"
    {
        bool asked = false;
        int SH = -1, dd0 = -1;
        MuCase c = kase("ghoti relay");
        c.actor = o;
        c.actPick = stratPick;
        c.driveEarly = true;
        c.untilRound = 1;
        c.setup = [&](Game& g) {
            SH = g.players[o].homeSystem;
            auto& n = g.players[f].notes;
            n.erase(std::remove(n.begin(), n.end(), makeNote(f, kNoteFaction)), n.end());
            g.players[o].notes.push_back(makeNote(f, kNoteFaction));
            g.players[o].tradeGoods = 6;
            g.players[o].fleet = 7;  // (room for 2 more ships at home)
            dd0 = 0;
            for (const SystemState& sy : g.systems) dd0 += sy.space[o].count(UnitType::Destroyer);
            return true;
        };
        auto relayAt = std::make_shared<int>(-1);
        c.drive = [&, relayAt](const Game&, const Decision& d, Answer& a) {
            if (d.player == o && d.tag == Tag::Faction && d.ability == int(Ab::DsGhotiRelay) && !asked) {
                asked = true;
                *relayAt = has(d, SH) ? SH : d.options[0].id;
                return pickOne(a, *relayAt);
            }
            if (d.player == o && d.kind == DecisionKind::Produce && d.system == *relayAt && *relayAt >= 0) {
                *relayAt = -2;
                return planFor(a, {{DD, 2}});
            }
            return false;
        };
        MuResult r = muRun(c);
        const auto& back = r.end.players[f].notes;
        const bool home = std::find(back.begin(), back.end(), makeNote(f, kNoteFaction)) != back.end();
        const auto& inPlay = r.atAct.players[o].notesInPlay;
        const bool played = std::find(inPlay.begin(), inPlay.end(), makeNote(f, kNoteFaction)) != inPlay.end();
        int dd1 = 0;
        for (const SystemState& sy : r.atAct.systems) dd1 += sy.space[o].count(UnitType::Destroyer);
        report("13 Ghoti Relay", asked && played && dd1 == dd0 + 2 && home,
               std::string(asked ? "Sol offered it at the start of its turn" : "NOT offered") + (played ? ", in its play area" : "") + ", " + std::to_string(dd1 - dd0) +
                   " destroyers made (2)" + (home ? ", back with the Ghoti after the status phase starts" : ", NOT back"));
    }
