    // ---- 16 / 17. Becece for another player: Sol produces at home - a person Ghoti, nothing promised (16); a bot Ghoti that promised
    // its agent to Sol (17)
    for (int k = 0; k < 2; ++k) {
        int SH = -1;
        bool asked = false;
        std::vector<int> none;
        MuCase c = kase(k ? "becece promised" : "becece person");
        c.actor = o;
        c.setup = [&](Game& g) {
            SH = g.players[o].homeSystem;
            g.players[o].tradeGoods = 10;
            if (k) g.agentFor[f] = int8_t(o);
            else g.players[f].human = true;
            freeTokens(g, o, 6);
            return true;
        };
        auto done = std::make_shared<bool>(false);
        c.drive = actDrive(o, &SH, &none, nullptr, [&, done](const Game&, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::DsBecece)) {
                asked = true;
                if (k) return false;  // (the bot answers)
                return pickOne(a, 2);
            }
            if (!*done && d.player == o && d.kind == DecisionKind::Produce && d.system == SH) {
                *done = true;
                return planFor(a, {{DD, 1}});
            }
            return false;
        });
        MuResult r = muRun(c);
        const bool used = lineWith(r, "from the caretaker") || lineWith(r, "grows by 2 (Becece)");
        if (k == 0) report("16 Becece for Sol (a person's agent)", r.acted && asked && used, std::string(asked ? "offered" : "NOT offered") + (used ? ", used" : ""));
        else report("17 Becece promised to Sol (a bot)", r.acted && asked && used, std::string(asked ? "offered" : "NOT offered") + (used ? ", used" : ", NOT used"));
    }
    // ---- 18 / 19. Ceie Doleegueaunm (commander): unlocked with "units in 3 systems that do not contain planets" (18); "After you activate
