    // ---- 14 / 15 / 16. Captain Dust (agent): "At the start of a player's turn: You may exhaust this card to allow that player to reveal
    // the top 2 cards of an exploration deck that matches a planet they control; they gain any relic fragments that they revealed and
    // discard the rest" - their own turn (14); Sol's turn, the Kollecc a person (15); Sol's turn, a bot that promised it to Sol (16).
    // The cultural deck alternates fragments and Mercenary Outfits: any 2 cards in a row give 1 fragment and 1 discard.
    for (int k = 0; k < 3; ++k) {
        bool asked = false;
        int frag0 = 0, disc0 = 0;
        const int who = k == 0 ? f : o;
        MuCase c = kase(k == 0 ? "captain dust" : k == 1 ? "captain dust sol" : "captain dust promised");
        c.actor = who;
        c.act = 99;
        c.driveEarly = true;
        c.setup = [&](Game& g) {
            culturalDeck(g);
            if (culturalPlanetFor(g, who) < 0) return false;
            for (Player& pq : g.players) pq.cardsUsed = 0xFF;  // (their card used: they may pass)
            setLeader(g, f, kAgent, kReady);
            if (k == 1) g.players[f].human = true;
            if (k == 2) {
                Promise pr;
                pr.kind = PromiseKind::UseAgent;
                pr.by = int8_t(f);
                pr.to = int8_t(o);
                pr.rounds = 1;
                pr.untilRound = int8_t(g.round + 1);
                g.promises.push_back(pr);
                g.agentFor[f] = int8_t(o);
            }
            frag0 = int(g.players[size_t(who)].fragments.size());
            disc0 = 0;
            return true;
        };
        c.drive = [&](const Game&, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::DsCaptainDust)) {
                const bool forWho = k == 0 ? (d.targetPlayer < 0 || d.targetPlayer == f) : d.targetPlayer == o;
                if (k == 2) {  // (the bot answers - for Sol only)
                    if (d.targetPlayer == o) asked = true;
                    return false;
                }
                if (!forWho) return pickOne(a, -1);
                asked = true;
                return has(d, CUL) ? pickOne(a, CUL) : false;
            }
            if (d.player == f && d.tag == Tag::Faction && (d.ability == int(Ab::DsTreasure) || d.ability == int(Ab::DsAiSurvey))) return pickOne(a, -1);
            return false;
        };
        MuResult r = muRun(c);
        const int got = int(r.end.players[size_t(who)].fragments.size()) - frag0;
        int mo = 0;
        for (int16_t x : r.end.exploreDiscard[size_t(CUL)]) mo += x == MO ? 1 : 0;
        bool kept = true;
        if (k == 2) {
            kept = false;
            for (const Promise& pr : r.end.promises)
                if (pr.kind == PromiseKind::UseAgent && pr.by == f && pr.to == o) kept = pr.state == kPromiseKept;
        }
        const char* nm = k == 0 ? "14 Captain Dust (their own turn: 2 cultural cards, the fragment kept, the other discarded)"
                         : k == 1 ? "15 Captain Dust (Sol's turn, the Kollecc a person)"
                                  : "16 Captain Dust (Sol's turn, a bot that promised it to Sol)";
        report(nm, r.acted && asked && got >= 1 && mo >= 1 && kept,
               std::string(asked ? "offered" : "NOT offered") + ", " + (k == 0 ? "the Kollecc" : "Sol") + " +" + std::to_string(got) + " fragments, " + std::to_string(mo) +
                   " discarded" + (k == 2 ? (kept ? ", the promise kept" : ", the promise NOT kept") : ""));
        (void)disc0;
    }
    // ---- 17 / 18. Kado S'mah-Qar (commander): unlocked with "4 relic fragments" (17); "This card satisfies a blue technology prerequisite"
