    // ---- 11 / 12. Rapid Excavation (note): "At the start of your turn: You may move up to 2 PDS units you control to a planet you control.
    // Then, return this card to the Mirveda player" - Sol with PDS on 3 planets moves 2 to its home planet (11), the 2 it chooses (12)
    {
        int SH = -1, J = -1;
        std::vector<int> src, want;
        bool asked = false, chose = false;
        int nth = 0;
        const int16_t note = int16_t(makeNote(f, kNoteFaction));
        MuCase c = kase("rapid excavation");
        c.actor = o;
        c.driveEarly = true;
        c.actPick = [](const Game&, const Decision& d) { return d.options.empty() ? -1 : d.options[0].id; };
        c.setup = [&](Game& g) {
            SH = g.players[o].homeSystem;
            J = g.systems[size_t(SH)].planets[0];
            std::vector<int> avoid;
            for (const Player& pl : g.players) avoid.push_back(pl.homeSystem);
            for (int i = 0; i < 3; ++i) {
                const int x = freePlanet(g, avoid);
                if (x < 0) return false;
                g.planets[size_t(x)].owner = int8_t(o);
                g.planets[size_t(x)].units[o].add(UnitType::PDS, 1);
                avoid.push_back(g.planets[size_t(x)].system);
            }
            for (int x : controlledPlanets(g, o))
                if (g.planets[size_t(x)].units[o].count(UnitType::PDS)) src.push_back(x);
            if (src.size() != 3) return false;
            want = {src[1], src[2]};  // (not the first one)
            g.planets[size_t(J)].units[o].n[PDS] = 0;
            auto& h = g.players[f].notes;
            h.erase(std::remove(h.begin(), h.end(), note), h.end());
            g.players[o].notes.push_back(note);
            return true;
        };
        c.drive = [&](const Game&, const Decision& d, Answer& a) {
            if (d.player != o || d.tag != Tag::Faction || d.ability != int(Ab::DsExcavation)) return false;
            asked = true;
            if (has(d, J) && d.prompt.find("to which planet") != std::string::npos) return pickOne(a, J);
            if (nth < 2 && has(d, want[size_t(nth)])) {
                chose = true;
                return pickOne(a, want[size_t(nth++)]);
            }
            return false;
        };
        MuResult r = muRun(c);
        const auto& kh = r.end.players[f].notes;
        const bool back = std::find(kh.begin(), kh.end(), note) != kh.end();
        const int onJ = J < 0 ? -1 : r.end.planets[size_t(J)].units[o].count(UnitType::PDS);
        bool right = src.size() == 3;
        if (right) {
            right = r.end.planets[size_t(src[0])].units[o].count(UnitType::PDS) == 1;
            for (int x : want) right = right && r.end.planets[size_t(x)].units[o].count(UnitType::PDS) == 0;
        }
        report("11 Rapid Excavation (2 PDS to Sol's home planet; the note back)", asked && onJ == 2 && back,
               std::string(asked ? "played" : "NOT offered") + ", " + std::to_string(onJ) + " PDS there (2)" + (back ? ", back" : ", NOT back"));
        report("12 Rapid Excavation (\"up to 2 PDS units you control\": the ones Sol chooses)", asked && chose && right,
               std::string(chose ? "asked which" : "NOT asked which") + (right ? ", those moved" : ", other ones moved"));
    }
    // ---- 13 / 14. Logic Machina (agent): "After a player gains a unit upgrade technology: You may exhaust this card to allow that player to
    // spend 1 command token from their strategy pool to research 1 technology of the same color as any 1 of that unit upgrade's
    // prerequisites" - the Mirveda research Fighter II with Technology, then a green or blue technology (13); Stabilization Arrays: "If you
    // have the Fighter II unit upgrade technology, flip this card and place it on top of Fighter II" - their fighters become the Eye of the
    // Curator (14)
    {
        bool asked = false;
        int first = 0, second = -1, st0 = -1;
        MuCase c = kase("logic machina");
        c.modules = DS | TE;
        c.driveEarly = true;
        c.actPick = [](const Game&, const Decision& d) {
            for (const Option& op : d.options)
                if (op.id == 16) return 16;
            return 0;
        };
        auto pickCard = strategyFor(f, 6);
        c.setup = [&](Game& g) {
            giveTech(g, f, "nm");
            giveTech(g, f, "amd");
            g.players[f].breakthrough = true;
            return true;
        };
        c.atActSet = [&](Game& g) { st0 = g.players[f].strategy; };
        c.drive = [&](const Game& g, const Decision& d, Answer& a) {
            if (pickCard(d, a)) return true;
            if (d.player == f && d.tag == Tag::Research) {
                if (first++ == 0) return pickOne(a, has(d, findTech("ff2")) ? findTech("ff2") : d.options[0].id);
                second = d.options[0].id;
                return pickOne(a, second);
            }
            if (d.player == f && d.tag == Tag::ExtraResearch) return pickOne(a, 0);
            if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::DsLogicMachina)) {
                asked = true;
                return pickOne(a, 1);
            }
            (void)g;
            return false;
        };
        MuResult r;
        for (uint32_t sd = 0; sd < 40; ++sd) {
            c.seed = 9090 + sd * 71;
            asked = false;
            first = 0;
            second = -1;
            r = muRun(c);
            if (r.acted && r.atAct.cardOwner[6] == f) break;
        }
        const Player& pe = r.end.players[f];
        const bool ff2 = pe.hasTech(findTech("ff2"));
        const bool colour = second >= 0 && pe.hasTech(second) &&
                            (kTechs[size_t(second)].color == TechColor::Green || kTechs[size_t(second)].color == TechColor::Blue);
        report("13 Logic Machina (Fighter II, then a green or blue technology for a strategy token)", r.acted && asked && ff2 && colour && pe.strategy == st0 - 1,
               std::string(asked ? "offered" : "NOT offered") + (colour ? ", " + std::string(kTechs[size_t(second)].name) + " researched" : ", NO second technology") +
                   ", strategy tokens " + std::to_string(st0) + " -> " + std::to_string(pe.strategy));
        const bool eye = ff2 && !std::strcmp(kUnits[size_t(pe.unit[FF])].key, "mirveda_fighter3");
        report("14 Stabilization Arrays (Fighter II researched with it: the Eye of the Curator)", r.acted && eye, eye ? "the Eye of the Curator" : "NOT flipped");
    }
