    // ---- 10. Psychoactive Armaments: "for each of their units that did not produce a hit, you may reroll that unit's combat roll" - a
    // war sun (3 dice) that hit with 1 or 2 of them doesn't roll again; a dreadnought that missed does
    {
        int tries = 0, expect = -1, got = -1, allMiss = -1;
        bool partial = false;
        for (uint32_t k = 0; k < 10 && !partial; ++k) {
            Fight fi;
            MuCase c = kase("psychoactive per unit");
            c.seed = 9090 + k * 37;
            c.actor = l;
            c.setup = [&](Game& g) {
                fi.H = g.players[f].homeSystem;
                fi.T = firstAdj(g, fi.H, 0);
                if (fi.T < 0) return false;
                fi.A = otherAdj(g, fi.T, fi.H);
                if (fi.A < 0) return false;
                g.systems[size_t(fi.A)].space[l].add(UnitType::WarSun, 1);
                g.systems[size_t(fi.A)].space[l].add(UnitType::Dreadnought, 1);
                fi.mv = {fi.A, -1, WS, 1, fi.A, -1, DN, 1};
                freeTokens(g, l, 8);
                giveTech(g, f, "dsmykog");
                setLeader(g, l, kAgent, kExhausted);  // (Viscount Unlenn's extra die would blur the units' dice)
                return true;
            };
            c.atActSet = [&](Game& g) {
                g.systems[size_t(fi.T)].space[f].add(UnitType::Dreadnought, 2);
                g.systems[size_t(fi.T)].space[f].add(UnitType::Carrier, 2);
                g.players[l].tradeGoods = 0;
                omen(g, f, 0, 0, 0, 0);
            };
            c.drive = actDrive(l, &fi.T, &fi.mv, nullptr, [&](const Game&, const Decision& d, Answer& a) {
                if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::DsPsychoactive)) return pickOne(a, 1);
                if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::DsLactarius)) return pickOne(a, -1);
                return false;
            });
            MuResult r = muRun(c);
            ++tries;
            const MuRoll x = rollOf(r, l, "Combat round 1");
            MuRoll y;  // Psychoactive Armaments in round 1: before Letnev's round-2 roll
            for (const MuRoll& z : r.rolls) {
                if (z.player == l && z.label.find("Combat round 2") != std::string::npos) break;
                if (z.player == f && z.label.find("Psychoactive") != std::string::npos) {
                    y = z;
                    break;
                }
            }
            int wsHit = 0, wsDice = 0, dnMiss = 0, miss = 0;
            for (size_t i = 0; i < x.dice.size(); ++i) {
                const bool hit = x.dice[i] >= x.need[i];
                miss += hit ? 0 : 1;
                if (x.need[i] <= 3) {
                    ++wsDice;
                    wsHit += hit ? 1 : 0;
                } else if (!hit) {
                    ++dnMiss;
                }
            }
            if (wsDice == 3 && wsHit >= 1 && wsHit <= 2) {
                partial = true;
                expect = dnMiss;
                got = int(y.dice.size());
                allMiss = miss;
            }
        }
        report("10 Psychoactive Armaments (per unit: a war sun with a hit doesn't roll again)", partial && got == expect,
               partial ? std::to_string(got) + " dice rolled again (" + std::to_string(expect) + " by unit, " + std::to_string(allMiss) + " missed dice)"
                       : "no war sun with 1-2 hits in " + std::to_string(tries) + " fights");
    }
