    {
        int B = -1, C = -1;
        bool off = false;
        MuCase c = kase("silence of space");
        c.setup = [&](Game& g) {
            const int H = g.players[f].homeSystem;
            if (!twoAway(g, H, B, C, -1)) return false;
            // (only one way through: every other system between H and C holds a Sol destroyer too)
            for (int16_t b : g.systems[size_t(H)].adj)
                if (adjTo(g, b, C) && !g.systems[size_t(b)].offBoard) g.systems[size_t(b)].space[o].add(UnitType::Destroyer, 1);
            onlyTechs(g, f, {});
            clearShips(g, f, H);
            g.systems[size_t(H)].space[f].add(UnitType::Cruiser, 1);
            freeTokens(g, f, 4);
            return true;
        };
        c.atActSet = [&](Game& g) { give(g, f, "silence_space"); };
        c.drive = moveDrive(f, [&] { return C; }, [&] { return std::vector<int>{}; }, play(f, "silence_space", off, [&](const Game& g, const Decision& d, Answer& a) {
                                if (d.player == f && d.tag == Tag::CardTarget && has(d, g.players[f].homeSystem)) return pickOne(a, g.players[f].homeSystem);
                                if (d.player == f && d.tag == Tag::Movement) {
                                    a = Answer{};
                                    a.data = {g.players[f].homeSystem, -1, CA, 1};
                                    return true;
                                }
                                return false;
                            }));
        MuResult r = muRun(c);
        const bool there = C >= 0 && r.end.systems[size_t(C)].space[f].count(UnitType::Cruiser) == 1;
        report("A5 In The Silence Of Space", r.acted && off && there, std::string(off ? "played" : "NOT offered") + (there ? ", through Sol's ships" : ", NOT through"));
    }
