    // ---- B18. Ghost Squad (Sol): "After another player commits units to land on a planet you control: Move any number of your
    // ground forces from any planet you control in the active system to any other planet you control in the active system"
    {
        int T = -1, P0 = -1, P1 = -1, inf0 = -1;
        bool off = false;
        MuCase c = kase("ghost squad");
        c.setup = [&](Game& g) {
            const int H = g.players[f].homeSystem;
            T = firstAdj(g, H, 2);
            if (T < 0) return false;
            P0 = g.systems[size_t(T)].planets[0], P1 = g.systems[size_t(T)].planets[1];
            for (int x : {P0, P1}) {
                g.planets[size_t(x)].owner = int8_t(o);
                g.planets[size_t(x)].units[o].add(UnitType::Infantry, 2);
            }
            onlyTechs(g, f, {});
            onlyTechs(g, o, {});
            clearShips(g, f, H);
            g.systems[size_t(H)].space[f].add(UnitType::Carrier, 1);
            g.systems[size_t(H)].space[f].add(UnitType::Infantry, 3);
            freeTokens(g, f, 4);
            return true;
        };
        c.atActSet = [&](Game& g) { give(g, o, "ghost_squad"); };
        c.drive = moveDrive(f, [&] { return T; }, [&] { return std::vector<int>{}; }, play(o, "ghost_squad", off, [&](const Game& g, const Decision& d, Answer& a) {
                                if (d.player == f && d.tag == Tag::Movement) {
                                    const int H = g.players[f].homeSystem;
                                    a = Answer{};
                                    a.data = {H, -1, CV, 1, H, -1, INF, 3};
                                    return true;
                                }
                                if (d.player == f && d.tag == Tag::LandForces) {
                                    a = Answer{};
                                    a.data = {P0, INF, 3};
                                    return true;
                                }
                                if (d.player == o && d.prompt.find("Ghost Squad: move all ground forces") == 0) {  // (the old rules)
                                    inf0 = 1;
                                    a = Answer{};
                                    a.picks = {P1};
                                    return true;
                                }
                                if (d.player == o && d.prompt.find("Ghost Squad: move from") == 0) {  // (fixes 27: a move at a time)
                                    const bool firstMove = inf0 != 1;
                                    inf0 = 1;
                                    return pickOne(a, firstMove && has(d, P1) ? P1 : -1);
                                }
                                if (d.player == o && d.prompt.find("Ghost Squad: move to") == 0) return pickOne(a, has(d, P0) ? P0 : d.options[0].id);
                                if (d.player == o && d.prompt.find("Ghost Squad: how many") == 0) return pickOne(a, d.options.back().id);
                                if (d.tag == Tag::SpaceCannonFire) return pickOne(a, 0);
                                return false;
                            }));
        MuResult r = muRun(c);
        report("B18 Ghost Squad", r.acted && off && inf0 == 1 && lineWith(r, "Ground combat"), std::string(off ? "played" : "NOT offered") + (inf0 == 1 ? ", Sol moved the other planet's infantry over" : ", NOTHING moved"));
    }
