        MuResult r = muRun(c);
        report("C6 Veto", r.acted && off && !lineWith(r, "Incentive Program:"), std::string(off ? "played" : "NOT offered") + (lineWith(r, "Incentive Program:") ? ", Incentive Program RESOLVED" : ", another agenda voted on instead"));
