        c.drive = play(f, "dp", off, [&](const Game&, const Decision& d, Answer& a) {
            if (d.tag == Tag::GiveNote && d.prompt.find("Diplomatic Pressure: give Hacan") == 0) gave = true;
            return passLater(d, a, f);
        });
        MuResult r = muRun(c);
