    // ---- C14 / C15. Confusing Legal Text: "When you are elected as the outcome of an agenda: Choose 1 player. That player is the
    // elected player instead"; Confounding Legal Text: "When another player is elected as the outcome of an agenda: You are the
    // elected player instead" - Minister of War, everyone votes for the Hacan / the Letnev
    for (int k = 0; k < 2; ++k) {
        const char* key = k ? "confounding" : "confusing";
        bool off = false;
        MuCase c = later(key, 1, true, "minister_war");
        c.atActSet = [&](Game& g) { give(g, f, key); };
        const int target = k ? 0 : f;
        c.drive = play(f, key, off, [&](const Game& g, const Decision& d, Answer& a) {
            if (d.tag == Tag::VoteOutcome && g.currentAgenda == findAgenda("minister_war") && has(d, target)) return pickOne(a, target);
            if (d.player == f && d.tag == Tag::CardTarget && has(d, 0)) return pickOne(a, 0);
            return passLater(d, a, f);
        });
        MuResult r;
        for (uint32_t sd = 0; sd < 20; ++sd) {
            off = false;
            c.seed = 9090 + sd * 61;
            r = muRun(c);
            if (lineWith(r, "Agenda: Minister of War")) break;
        }
        int owner = -9;
        for (const Law& l : r.end.laws)
            if (l.agenda == findAgenda("minister_war")) owner = l.owner;
        const int want = k ? f : 0;
        report(k ? "C15 Confounding Legal Text" : "C14 Confusing Legal Text", r.acted && off && owner == want,
               std::string(off ? "played" : "NOT offered") + ", Minister of War held by seat " + std::to_string(owner) + " (" + std::to_string(want) + ")");
    }
    // ---- C16. Deadly Plot: "During the agenda phase, when an outcome would be resolved: If you voted for or predicted another
    // outcome, discard the agenda instead. The agenda is resolved with no effect and it is not replaced. Then, exhaust all of
    // your planets" - the Hacan vote against what everyone else votes for
    {
        bool off = false;
        int mine = -999, allExNow = -1;
        MuCase c = later("deadly plot", 1, true, "incentive");
        c.atActSet = [&](Game& g) { give(g, f, "deadly_plot"); };
        c.drive = play(f, "deadly_plot", off, [&](const Game& g, const Decision& d, Answer& a) {
            if (g.agendaNumber == 1 && allExNow < 0) {
                allExNow = 1;
                for (int x : controlledPlanets(g, f)) allExNow = allExNow && g.planets[size_t(x)].exhausted;
            }
            if (d.tag == Tag::VoteOutcome && g.currentAgenda == findAgenda("incentive")) {
                std::vector<int> ids;
                for (const Option& op : d.options)
                    if (op.enabled && op.id != -100) ids.push_back(op.id);
                if (ids.size() < 2) return false;
                if (d.player == f) mine = ids[1];
                return pickOne(a, d.player == f ? ids[1] : ids[0]);
            }
            return passLater(d, a, f);
        });
        MuResult r = muRun(c);
        const bool allEx = allExNow == 1;
        report("C16 Deadly Plot", r.acted && off && lineWith(r, "is discarded by Deadly Plot") && allEx,
               std::string(off ? "played" : "NOT offered") + (lineWith(r, "is discarded by Deadly Plot") ? ", the agenda discarded" : ", RESOLVED") + (allEx ? ", the Hacan planets exhausted" : ""));
    }
    // ================================================================ the findings (fail with the old rules)
    // ---- F1. Manipulate Investments: "Place a total of 5 trade goods ... on strategy cards of your choice. You must place these
    // tokens on at least 3 different cards" - 3 on one card, 1 on two others (the old rules spread them 2 / 2 / 1)
    {
        bool off = false, oldWay = false;
        int A = -1, n = 0;
        std::vector<int> used;
        int base[kStrategyCards] = {}, after[kStrategyCards] = {};
        bool snapped = false;
        MuCase c = later("investments split", 2, false, nullptr);
        c.atActSet = [&](Game& g) { give(g, f, "investments"); };
        c.drive = play(f, "investments", off, [&](const Game& g, const Decision& d, Answer& a) {
            if (d.player == f && d.prompt.find("Manipulate Investments: choose 3 to 5") == 0) oldWay = true;
            if (d.player == f && d.prompt.find("Manipulate Investments: trade good") == 0) {
                if (A < 0) {
                    A = d.options[0].id;
                    for (int k = 0; k < kStrategyCards; ++k) base[k] = g.cardTradeGoods[k];
                }
                int pickId = A;
                if (n >= 3)
                    for (const Option& op : d.options)
                        if (op.enabled && op.id != A && std::find(used.begin(), used.end(), op.id) == used.end()) {
                            pickId = op.id;
                            break;
                        }
                used.push_back(pickId);
                ++n;
                return pickOne(a, pickId);
            }
            if (n == 5 && !snapped && d.tag == Tag::StrategyPick) {
                snapped = true;
                for (int k = 0; k < kStrategyCards; ++k) after[k] = g.cardTradeGoods[k];
            }
            return passLater(d, a, f);
        });
        MuResult r = muRun(c);
        const int onA = A >= 0 && snapped ? after[A] - base[A] : -1;
        report("F1 Manipulate Investments (any split)", r.acted && off && onA == 3,
               oldWay ? "the old rules: 3 to 5 cards, spread evenly (no 3 / 1 / 1)" : std::to_string(onA) + " trade goods on the first card (3)");
    }
