    // ================================================================ component actions (the Hacan play them as their action)
    auto comp = [&](const char* name, const char* key, std::function<bool(Game&)> more) {
        MuCase c = kase(name);
        c.act = 1000 + AC(key);
        c.setup = [=](Game& g) {
            if (more && !more(g)) return false;
            give(g, f, key);
            return true;
        };
        return c;
    };
    auto ownTrait = [&](Game& g, Trait tr, bool exhausted) {  // a non-home planet with that trait for the Hacan
        for (size_t x = 0; x < g.planets.size(); ++x) {
            PlanetState& ps = g.planets[x];
            if (ps.system < 0 || ps.owner >= 0 || g.systems[size_t(ps.system)].home >= 0 || !hasTraitOf(g, int(x), tr)) continue;
            ps.owner = int8_t(f);
            ps.exhausted = exhausted;
            return int(x);
        }
        return -1;
    };
    auto solPlanet = [&](Game& g, int planets) {  // a planet next to the Hacan home for Sol
        const int T = firstAdj(g, g.players[f].homeSystem, planets);
        if (T < 0) return -1;
        const int P = g.systems[size_t(T)].planets[0];
        g.planets[size_t(P)].owner = int8_t(o);
        return P;
    };
