    // any relic fragments that you reveal and discard the rest"
    {
        MuCase c = comp("archaeological expedition", "arch_expedition", [&](Game& g) { return ownTrait(g, Trait::Cultural, false) >= 0; });
        MuResult r = muRun(c);
        report("E1 Archaeological Expedition", playedBy(r, f, "arch_expedition") && lineWith(r, "Hacan reveals"), lineWith(r, "Hacan reveals") ? "3 cards revealed" : "NOT played");
    }
