    // ships"
    {
        int E = -1;
        MuCase c = comp("exploration probe", "probe", [&](Game& g) {
            E = -1;
            for (size_t s = 0; s < g.systems.size() && E < 0; ++s) {
                if (!g.systems[s].frontier) continue;
                for (int16_t x : g.systems[s].adj)
                    if (plainSys(g, x, -1)) {
                        E = int(s);
                        g.systems[size_t(x)].space[f].add(UnitType::Cruiser, 1);
                        break;
                    }
            }
            return E >= 0;
        });
        MuResult r = muRun(c);
        const bool gone = E >= 0 && !r.end.systems[size_t(E)].frontier;
        report("E2 Exploration Probe", playedBy(r, f, "probe") && gone, gone ? "the frontier token explored" : "NOT explored");
    }
