        const int cr = r.after.systems[size_t(r.after.mecatol())].space[f].count(UnitType::Cruiser);
        report("5c Ixthian Artifact (Against): no effect", r.seen && cr == 2 && !lineWith(r, "for the Ixthian Artifact"), "cruisers at Mecatol 2 -> " + std::to_string(cr));
