        const bool ok = purged && !hasTechK(r.end, o, "nm") && !hasTechK(r.end, f, "nm") && r.end.players[o].techs.size() == sol0 && r.end.players[f].techs.size() == dw0 &&
                        leaderStatus(r.end, f, kHero) == kPurged;
        report("13 Ta Zern", r.acted && ok, std::string(purged ? "Neural Motivator purged" : "NOT purged") + ", Sol " + std::to_string(sol0) + " -> " +
                                                std::to_string(r.end.players[o].techs.size()) + " technologies, the Deepwrought " + std::to_string(dw0) + " -> " +
                                                std::to_string(r.end.players[f].techs.size()));
