    // ---- 17. D.W.S. Luminous (flagship): "This ship can move through systems that contain your units, even if other players'
    // units are present; if it would, apply +1 to its move value for each of those systems" - move 1: 3 systems away through 2
    // of theirs (Sol's destroyer in the first); without their units in the second only 2
    {
        bool far = false, near = true;
        MuCase c = kase("luminous");
        c.setup = [&](Game& g) {
            const int H = g.players[f].homeSystem;
            auto plain = [&](int s) {
                const SystemState& ss = g.systems[size_t(s)];
                if (ss.offBoard || ss.isHyperlane() || ss.home >= 0 || s == g.mecatol() || isAnomaly(g, s)) return false;
                for (int q = 0; q < kSides; ++q)
                    if (!ss.space[size_t(q)].empty()) return false;
                return true;
            };
            auto adjTo = [&](int a, int b) { return std::find(g.systems[size_t(a)].adj.begin(), g.systems[size_t(a)].adj.end(), int16_t(b)) != g.systems[size_t(a)].adj.end(); };
            int A = -1, B = -1, C = -1;
            for (int16_t a : g.systems[size_t(H)].adj) {
                if (!plain(a)) continue;
                for (int16_t b : g.systems[size_t(a)].adj) {
                    if (b == H || adjTo(H, b) || !plain(b)) continue;
                    for (int16_t cc : g.systems[size_t(b)].adj) {
                        if (cc == a || cc == H || adjTo(H, cc) || adjTo(a, cc) || !plain(cc)) continue;
                        bool two = false;  // (no shorter way: nothing next to both H's neighbours and cc)
                        for (int16_t x : g.systems[size_t(H)].adj)
                            for (int16_t y : g.systems[size_t(x)].adj)
                                if (adjTo(y, cc) && y != b) two = true;
                        if (two) continue;
                        A = a, B = b, C = cc;
                        break;
                    }
                    if (C >= 0) break;
                }
                if (C >= 0) break;
            }
            if (C < 0) return false;
            clearShips(g, f, H);
            g.systems[size_t(H)].space[f].add(UnitType::Flagship, 1);
            g.systems[size_t(A)].space[f].add(UnitType::Cruiser, 1);
            g.systems[size_t(A)].space[o].add(UnitType::Destroyer, 1);
            g.systems[size_t(B)].space[f].add(UnitType::Destroyer, 1);
            far = shipReach(g, f, H, C, UnitType::Flagship, 0).ok;
            g.systems[size_t(B)].space[f] = Force();
            near = shipReach(g, f, H, C, UnitType::Flagship, 0).ok;
            g.systems[size_t(B)].space[f].add(UnitType::Destroyer, 1);
            return true;
        };
        c.actPick = stratPick;
        MuResult r = muRun(c);
        report("17 D.W.S. Luminous", r.setUp && far && !near,
               std::string(far ? "3 systems away through 2 of theirs" : "NOT 3 away through 2 of theirs") + (near ? ", ALSO without the second" : ", not without the second"));
    }
    // ---- 18. Eanautic (mech): "When another player activates this system, if this unit is coexisting, you may move it and any of
    // your infantry on its planet to a planet you control in your home system" - Sol moves into the system: the mech and 2
    // infantry go home
    {
        int T = -1, P = -1, home0 = -1;
        bool asked = false;
        MuCase c = kase("eanautic");
        c.actor = o;
        c.setup = [&](Game& g) {
            const int HS = g.players[o].homeSystem;
            T = plainNext(g, HS);
            if (T < 0) return false;
            P = g.systems[size_t(T)].planets[0];
            PlanetState& ps = g.planets[size_t(P)];
            ps.owner = int8_t(o);
            ps.units[o].add(UnitType::Infantry, 1);
            ps.units[f].add(UnitType::Mech, 1);
            ps.units[f].add(UnitType::Infantry, 2);
            ps.coexist = uint16_t(ps.coexist | (1u << f));
            clearShips(g, o, HS);
            g.systems[size_t(HS)].space[o].add(UnitType::Dreadnought, 1);
            freeTokens(g, o, 3);
            return true;
        };
        c.atActSet = [&](Game& g) {
            home0 = 0;
            for (int16_t x : g.systems[size_t(g.players[f].homeSystem)].planets) home0 += g.planets[size_t(x)].units[f].groundForces();
        };
        c.drive = moveDrive(o, [&] { return T; }, [&] { return std::vector<int>{-1}; }, [&](const Game& g, const Decision& d, Answer& a) {
            if (d.player == f && d.tag == Tag::Faction && d.ability == int(Ab::Eanautic)) {
                asked = true;
                return pickOne(a, 1);
            }
            if (d.player == o && d.tag == Tag::Movement) {
                a = Answer{};
                a.data = {g.players[o].homeSystem, -1, DN, 1};
                return true;
            }
            if (d.player == o && d.tag == Tag::LandForces) {
                a = Answer{};
                return true;
            }
            return false;
        });
        MuResult r = muRun(c);
        int home1 = 0;
        for (int16_t x : r.end.systems[size_t(r.end.players[f].homeSystem)].planets) home1 += r.end.planets[size_t(x)].units[f].groundForces();
        const bool gone = P >= 0 && r.end.planets[size_t(P)].units[f].empty();
        report("18 Eanautic", r.acted && asked && gone && home1 == home0 + 3,
               std::string(asked ? "offered" : "NOT offered") + (gone ? ", the mech and 2 infantry home" : ", still THERE"));
    }
