        if (std::string(only) == "fracture") return fractureScreens(outDir) > 0 ? 0 : 1;
        if (std::string(only) == "obsidian") return obsidianScreens(outDir) > 0 ? 0 : 1;
        if (std::string(only) == "codec") return codecScreens(outDir) > 0 ? 0 : 1;
